 let mysteryClues=[['BLUE','The sky on a clear day is _____.'],['FIFTY','How many states are in the USA? Spell it out.'],['CLOCK','I have hands but cannot clap.'],['PIANO','What has keys but opens no locks?'],['JELLY','Peanut butter and _____.'],['HOT','The opposite of cold.'],['MOON','I shine at night but am not a star.'],['HONEY','What sweet treat do bees make?'],['ROBOT','A machine that can perform tasks automatically.'],['SHARK','A finned predator of the sea.'],['APPLE','A crunchy fruit that keeps doctors away, they say.'],['RAIN','What falls from clouds but is not snow?'],['STAR','A distant light twinkling in the night sky.'],['CROWN','A royal wears this on their head.'],['GHOST','A spooky visitor said to haunt houses.'],['MAGIC','A magician might perform this.'],['TRAIN','A vehicle that travels along railway tracks.'],['SMILE','What curves across your face when you are happy?'],['WIND','You cannot see me, but you can feel me blow.'],['SWORD','A knight might carry this into battle.']];let cluePool=[],clueUsed=new Set(); const chooseClue=()=>{const candidates=mysteryClues.filter(c=>!used.has(c[0])&&!clueUsed.has(c[0]));if(candidates.length){const clue=shuffle(candidates)[0];clueUsed.add(clue[0]);return clue;}const extras=words.filter(w=>!used.has(w)&&!clueUsed.has(w)&&w.length>=4&&w.length<=7);if(!extras.length)return null;const word=shuffle(extras)[0];clueUsed.add(word);return [word,`Find the hidden ${word.length}-letter word. Its first letter is ${word[0]}.`];}; let secret=null,secretFound=false,secretRevealed=false,secretPrompt=false,secretAttempts=0,eggHintShown=false,secretMessages=['IMPRESSIVE!','EAGLE EYES!','SECRET DISCOVERED!','GENIUS MOVE!','LEGENDARY FIND!','WHAT A CATCH!'],secretMessagePool=[],letUnused=0; let feedbackPools={},lastPracticeSignature='',messagePool=[],used=new Set(),mode='scrabble',phase='welcome',round=1,grid=[],placements=[],found=new Set(),drag=[],dragging=false,score=0,time=60,timer=null,quickSeen=new Set(),quickPaths=new Map(),quickPossible=new Set(),quickFound=new Set(),quickTierPools={};
