 const shuffle=a=>{for(let i=a.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a};
 const adjacent=(a,b)=>{let r=Math.abs(Math.floor(a/GRID_SIZE)-Math.floor(b/GRID_SIZE)),c=Math.abs(a%GRID_SIZE-b%GRID_SIZE);return Math.max(r,c)===1};
