 function pathFor(word,cells,turns){let candidates=[];for(let attempt=0;attempt<170;attempt++){let start=Math.floor(Math.random()*GRID_CELLS),path=[start],dir=directions[Math.floor(Math.random()*directions.length)];for(let i=1;i<word.length;i++){let prev=path.at(-1),r=Math.floor(prev/GRID_SIZE),c=prev%GRID_SIZE,options=[];for(let d of directions){if(!turns&&d!==dir)continue;let nr=r+d[0],nc=c+d[1],n=nr*GRID_SIZE+nc;if(nr>=0&&nr<GRID_SIZE&&nc>=0&&nc<GRID_SIZE&&!path.includes(n)&&(!cells[n]||cells[n]===word[i]))options.push(n)}if(!options.length)break;options.sort((a,b)=>(cells[b]===word[i]?1:0)-(cells[a]===word[i]?1:0));path.push(options[0])}if(path.length===word.length&&(!cells[start]||cells[start]===word[0]))candidates.push(path)}return candidates.length?shuffle(candidates)[0]:null}
 function build(target,practice=false,eggClue=null){let best=null;for(let attempt=0;attempt<95;attempt++){let cells=Array(GRID_CELLS).fill(''),chosen=[],eggPath=null,pool=practice?['HIRE','HIM','NOW']:shuffle(words.filter(w=>w!==eggClue?.[0]&&w.length<=Math.min(MAX_WORD_LENGTH,round<3?5:round<6?6:7))).sort((a,b)=>a.length-b.length);if(eggClue){eggPath=pathFor(eggClue[0],cells,true);if(!eggPath)continue;eggPath.forEach((n,i)=>cells[n]=eggClue[0][i]);}for(let w of pool){if(chosen.length===target)break;let path=pathFor(w,cells,practice||round>=7||mode==='quick');if(!path)continue;path.forEach((n,i)=>cells[n]=w[i]);chosen.push({word:w,path})}if(!best||chosen.length>best.chosen.length)best={cells,chosen,eggPath};if(chosen.length===target)break}if(!best||best.chosen.length!==target)return null;best.cells=best.cells.map(v=>v||'ABCDEFGHIJKLMNOPQRSTUVWXYZ'[Math.floor(Math.random()*26)]);return best}

 // On small grids, construct a legal secret path, then choose six actually traceable targets.
 // This avoids a dead START ROUND button when greedy word placement cannot fit seven words.
 function compactScrabbleBoard(eggClue){
  const secretWord=eggClue?.[0]||'STAR';
  const letters='EEEEAAAAIIIIOOOONNNNRRRRTTTTSSSSLLLLDDDDHHHCCMMUUPPGGBBFFWWYY';
  const eligible=words.filter(w=>w!==secretWord&&w.length>=MIN_WORD_LENGTH&&w.length<=Math.min(MAX_WORD_LENGTH,round<3?5:7));
  const findPath=(word,cells)=>{
   function walk(i,k,path,seen){if(cells[i]!==word[k])return null;const next=[...path,i];if(k===word.length-1)return next;for(let j=0;j<GRID_CELLS;j++)if(!(seen&(1<<j))&&adjacent(i,j)){const hit=walk(j,k+1,next,seen|(1<<j));if(hit)return hit}return null}
   for(let i=0;i<GRID_CELLS;i++){const hit=walk(i,0,[],1<<i);if(hit)return hit}return null;
  };
  let best=null;
  for(let attempt=0;attempt<450;attempt++){
   const cells=Array(GRID_CELLS).fill('');
   const eggPath=pathFor(secretWord,cells,true);
   if(!eggPath)continue;
   eggPath.forEach((n,i)=>cells[n]=secretWord[i]);
   // Seed additional short targets into remaining spaces, allowing letter overlap.
   const candidates=shuffle([...eligible]).sort((a,b)=>a.length-b.length);
   for(const w of candidates.slice(0,110)){
    const path=pathFor(w,cells,true);
    if(path)path.forEach((n,i)=>cells[n]=w[i]);
    if(cells.every(Boolean))break;
   }
   const board=cells.map(c=>c||letters[Math.floor(Math.random()*letters.length)]);
   const found=[];
   for(const w of eligible){const path=findPath(w,board);if(path)found.push({word:w,path})}
   const unused=found.filter(p=>!used.has(p.word));
   const chosen=shuffle(unused).slice(0,6);
   if(chosen.length<6){if(!best||found.length>best.chosen.length)best={cells:board,chosen:found.slice(0,6),eggPath};continue}
   return {cells:board,chosen,eggPath};
  }
  return best?.chosen.length===6?best:null;
 }
 function practiceBoard(){
  // Place each word afresh; do not transform a fixed practice board.
  const targets=['HIRE','HIM','NOW'];
  for(let attempt=0;attempt<500;attempt++){
   const cells=Array(GRID_CELLS).fill(''),chosen=[];
   for(const w of shuffle([...targets])){
    const path=pathFor(w,cells,true);
    if(!path)break;
    path.forEach((n,i)=>cells[n]=w[i]);chosen.push({word:w,path});
   }
   if(chosen.length!==3)continue;
   const signature=chosen.sort((a,b)=>targets.indexOf(a.word)-targets.indexOf(b.word)).map(p=>p.path.join('-')).join('|');
   if(signature===lastPracticeSignature)continue;
   lastPracticeSignature=signature;
   return {cells:cells.map(c=>c||'ABCDEFGHIJKLMNOPQRSTUVWXYZ'[Math.floor(Math.random()*26)]),chosen};
  }
  return build(3,true);
 }
