  $('whScrabbleLoadTitle').textContent='BUILDING ROUND '+round+'…';$('whScrabbleLoadText').textContent='Finding six words and a secret…';$('whScrabbleSpinner').hidden=false;$('whScrabbleRetry').hidden=true;
