 let quickPreparedBoard=null,quickPreparedWords=new Set();
 const quickLetters='AEIOUBCDFGHJKLMNPQRSTVWXYZXYZXYZXYZXYZXYZXYZ';
 // Fixed word-length mix across every Quick Draw round, not increasing with play count.
 // For a 20-word board, prefer 6/6/4/3/1 (lengths 3..7).
 const quickTargetShares=[.32,.28,.22,.12,.06];
 const quickSeedWords={
  5:['TRAIN','PLANT','STONE','SHINE','SWEET','SMILE','BREAD','LIGHT','WATER'],
  6:['PLANET','STREAM','GARDEN','ROCKET','ORANGE','BRIDGE','SILVER','FLOWER'],
  7:['MONSTER','PICTURE','JOURNEY','CAPTAIN','MORNING','ANOTHER','WEATHER']
 };
 function quickCandidate(seedLong=true){
  const cells=Array(GRID_CELLS).fill('');
  if(seedLong){
   // Seed fewer long words: a broader vocabulary can make the board exceed the maximum possible-word target.
   const sizes=shuffle([7,6]);
   for(const length of sizes){
    const candidates=shuffle([...quickSeedWords[length]].filter(w=>dictionary.has(w)));
    for(const w of candidates){
     const path=pathFor(w,cells,true);
     if(path){path.forEach((n,i)=>cells[n]=w[i]);break}
    }
   }
  }
  return {cells:cells.map(c=>c||quickLetters[Math.floor(Math.random()*quickLetters.length)]),chosen:[]};
 }
 function quickMixScore(possible){
  const n=possible.size;
  if(n<QUICK_MIN_WORDS||n>QUICK_MAX_WORDS)return 1000+Math.abs(n-QUICK_IDEAL_WORDS)*20;
  const counts=Array(MAX_WORD_LENGTH-MIN_WORD_LENGTH+1).fill(0);
  for(const w of possible)if(w.length>=MIN_WORD_LENGTH&&w.length<=MAX_WORD_LENGTH)counts[w.length-MIN_WORD_LENGTH]++;
  // A fixed distribution is a target, not a guarantee: incidental legal words count too.
  const deviation=counts.reduce((sum,c,i)=>sum+Math.abs(c-n*quickTargetShares[i]),0);
  const missingLong=0; // Longer words are a preference, never a board requirement.;
  return deviation+missingLong+Math.abs(n-QUICK_IDEAL_WORDS)*.25;
 }
 async function prepareQuickBoard(token){
  quickLoading=true;show('wordQuickLoading');$('whQuickCountdown').textContent='';quickLoadState('building');quickProgress(0,'Generating letters…');
  try{await loadQuickDictionary()}catch(e){quickLoadState('failed','Dictionary could not initialize.');quickLoading=false;return false}
  if(token!==quickRunToken)return false;
  quickProgress(6,'Checking valid words…');
  let best=null,bestScore=Infinity;
  // Compare actual traceable words, including accidental ones, against fixed targets.
  // Yield periodically to keep the phone responsive during board preparation.
  for(let i=0;i<600;i++){
   if(token!==quickRunToken||screen.hidden)return false;
   const candidate=quickCandidate(i%GRID_SIZE!==0),poss=enumerateQuick(candidate.cells);
   const score=quickMixScore(poss);
   if(poss.size>=QUICK_MIN_WORDS&&poss.size<=QUICK_MAX_WORDS&&score<bestScore){bestScore=score;best={candidate,poss}}
   if(i%3===0){quickProgress(6+84*(i+1)/600,i<30?'Checking valid words…':'Balancing word lengths…');await quickWait(0)}
   if(bestScore<8)break;
  }
  if(!best){quickLoadState('failed','Could not find a balanced 15–25-word grid.');quickLoading=false;return false}
  quickPreparedBoard=best.candidate;quickPreparedWords=best.poss;quickProgress(100,'PUZZLE READY!');quickLoadState('ready');return true;
 }
